\draw[dashed] (2,-4.3)--(2,5.3) node[above right] {$x=2$};
\draw[dashed] (-5.2,1)--(6.2,1) node[right] {$y=1$};
\draw[thick,curveBlue,<-,domain=-5.2:-2,samples=100] plot (\x,{(\x+2)/(\x-2)});
\draw[thick,curveBlue,->,domain=-2:1.2,samples=100] plot (\x,{(\x+2)/(\x-2)});
\draw[thick,curveBlue,<->,domain=3:6.2,samples=100] plot (\x,{(\x+2)/(\x-2)});
\draw[fill=white] (-2,0) circle (2pt);
\node[below left,yshift=-5pt] at (-2,0) {$(-2,0)$};
\fill (0,-1) circle (1.4pt);
\node[below left] at (0,-1) {$(0,-1)$};
\node[above right,text=curveBlue] at (4,3) {$g(x)$};
\end{tikzpicture}
[/tikz]

